variables.new:
{%- set prev = state_attr('sensor.ls_overrides', 'overrides') -%}
{%- set d = trigger.event.data -%}
{%- set op = d.get('op', 'set') -%}
{%- set rooms = (label_entities('house_schedule') + label_entities('on_off') + ((label_devices('house_schedule') + label_devices('on_off')) | map('device_entities') | sum(start=[]))) | map('area_id') | select | unique | list -%}
{%- set ns = namespace(o=(prev if prev is mapping else {})) -%}
{%- if op == 'clear_all' -%}
  {%- set ns.o = {} -%}
{%- elif op == 'clear' -%}
  {%- set ns.o = dict(ns.o.items() | rejectattr(0, 'in', d.get('keys', [])) | list) -%}
{%- elif op == 'set' -%}
  {%- set who = d.get('who') or trigger.event.context.user_id -%}
  {%- for r in d.get('records', []) -%}
    {%- if r.kind in ['block', 'mode'] -%}
      {%- set drop = namespace(k=[]) -%}
      {%- for k, v in ns.o.items() if k.startswith('light:') and v is mapping -%}
        {%- set la = area_id(v.target) -%}
        {%- set lsc = la if la in rooms else 'house' -%}
        {%- if (r.kind == 'mode' and la not in label_areas('private_room')) or lsc == r.target -%}{%- set drop.k = drop.k + [k] -%}{%- endif -%}
      {%- endfor -%}
      {%- set ns.o = dict(ns.o.items() | rejectattr(0, 'in', drop.k) | list) -%}
    {%- endif -%}
    {%- set ns.o = dict(ns.o, **{r.kind ~ ':' ~ r.target: {'kind': r.kind, 'target': r.target, 'value': r.get('value'), 'when': now().isoformat(), 'who': who, 'via': d.get('via')}}) -%}
  {%- endfor -%}
{%- endif -%}
{{ ns.o }}
